'use strict';
const $=id=>document.getElementById(id);
const state={lastRefreshed:null,etfPeriod:'monthly',etfMode:'stacked',etfRange:'all',view:'overview',feeds:{},period:365,log:false,macroMetric:'liquidity',search:'',allCompanies:false,busy:false,contextDays:1095,macroPeriod:365,eventMarkers:true,compareFrom:'',compareTo:'',archive:null,modelCutoff:'2023-12-31',modelPeriod:0,modelExtensions:{power:0,s2f:0,realized:0,ma200w:0},modelProjection:false,modelBands:false,modelWeekly:false};
const FEEDS=['spot','bitcoin','sentiment','adoption','macro','calendar','valuation','etf','supply'];
const PAGES={narratives:['THE STORIES AROUND BITCOIN','What’s moving the conversation.','News, fundamentals and network developments, ranked by coverage.'],models:['VALUATION & LONG-TERM CONTEXT','Price through different lenses.','Compare models, inspect their assumptions, and see where they fall short.'],overview:['THE DAILY PICTURE','A little perspective.','Bitcoin, capital flows, and the forces around them.'],bitcoin:['PRICE, TREND & NETWORK','Understand the asset.','Market structure and the network behind it, in one place.'],adoption:['OWNERSHIP & CAPITAL','Follow the commitment.','Track reported corporate ownership and explore institutional demand.'],macro:['LIQUIDITY, RATES & THE ECONOMY','The bigger picture.','The monetary and economic conditions surrounding Bitcoin.'],sources:['TRANSPARENCY BY DESIGN','Know what you’re reading.','Source health, observation dates, and the assumptions behind each indicator.']};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const valid=value=>typeof value==='number'&&Number.isFinite(value);
const num=(value,digits=0)=>valid(value)?new Intl.NumberFormat('en-US',{maximumFractionDigits:digits,minimumFractionDigits:digits}).format(value):'—';
const money=(value,digits=0)=>valid(value)?`$${num(value,digits)}`:'—';
const percent=(value,digits=1,sign=false)=>valid(value)?`${sign&&value>0?'+':''}${num(value,digits)}%`:'—';
const delta=(value,suffix='',digits=1)=>valid(value)?`${value>0?'+':''}${num(value,digits)}${suffix}`:'—';
const compact=value=>valid(value)?new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(value):'—';
const date=value=>value?new Date(value.length===10?`${value}T12:00:00Z`:value).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}):'Date not supplied';
const tone=value=>!valid(value)?'neutral':value>=0?'positive':'negative';
const fresh=key=>state.feeds[key]?.status==='current';
const data=key=>state.feeds[key]?.data;
function badge(status){return `<span class="badge ${status==='current'?'good':status==='stale'?'warn':'quiet'}">${status==='current'?'Current':status==='stale'?'Stale':status==='unavailable'?'Unavailable':'Loading'}</span>`;}
function empty(key,label='Data unavailable') {return !state.feeds[key]?'<div class="empty">Connecting to source…<div class="loading-bar" style="width:150px"></div></div>':`<div class="empty">${label}<span>The source did not return usable data. Refresh to retry; other sections remain available.</span></div>`;}
function source(key,extra='') {
 const f=state.feeds[key],d=f?.data;if(!d)return `<div class="source-line">${f?'Source unavailable':'Loading source…'}</div>`;
 const when=d.asOf?`${d.timestampKind==='retrieved'?'Fetched':'As of'} ${date(d.asOf)}${d.asOf.includes('T')?' · '+new Date(d.asOf).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}):''}`:`Fetched ${date(f.retrievedAt)} · reporting dates unavailable`;
 return `<div class="source-line"><a href="${esc(d.url)}" target="_blank" rel="noreferrer">${esc(d.source)} ↗</a> · ${when}${f.status==='stale'?' · <strong>STALE — may not reflect current conditions</strong>':''}${extra?` · ${esc(extra)}`:''}</div>`;
}
function spark(points,color='#889e77') {
 const values=(points||[]).slice(-35).map(p=>p.value).filter(valid);if(values.length<2)return '';
 const min=Math.min(...values),span=Math.max(...values)-min||1;
 const d=values.map((v,i)=>`${i?'L':'M'}${(i/(values.length-1)*80).toFixed(1)},${(22-(v-min)/span*20).toFixed(1)}`).join(' ');
 return `<svg class="spark" viewBox="0 0 80 24" aria-hidden="true"><path d="${d}" fill="none" stroke="${color}" stroke-width="1.5"/></svg>`;
}
function stat(title,value,note,bottom,series=[],symbol='↗',textual=false) {return `<article class="card"><div class="metric-top"><p class="kicker">${title}</p><span class="metric-symbol" aria-hidden="true">${symbol}</span></div><p class="stat-value ${textual?'textual':''}">${value}</p><p class="stat-note">${note}</p><div class="stat-bottom"><span>${bottom}</span>${spark(series)}</div></article>`;}
function section(title,link,label){return `<div class="section-label"><h2>${title}</h2>${link?`<a href="#${link}">${label||'Explore'} ↗</a>`:''}</div>`;}
function signal(label,value,detail='',className=''){return `<div class="signal-row"><div>${label}${detail?`<small>${detail}</small>`:''}</div><strong class="right ${className}">${value}</strong></div>`;}
function trend(b){return !b||!valid(b.ma200)||!valid(b.ma50)?'Awaiting data':b.close>b.ma200?(b.close>b.ma50?'Above key averages':'Mixed trend'):(b.close<b.ma50?'Below key averages':'Mixed trend');}
function topStats() {
 const b=data('bitcoin'),s=data('sentiment'),a=data('adoption'),m=data('macro')?.metrics?.liquidity;
 return `<div class="grid grid-four">${stat('Bitcoin trend',trend(b),b?`<span class="${tone(b.returns.day30)}">${percent(b.returns.day30,1,true)}</span> over 30 days · daily closes`:'Waiting for daily price history',b?`${fresh('bitcoin')?'As of':'Stale ·'} ${date(b.asOf)}`:'Daily close',b?.history,'₿',true)}${stat('Market sentiment',s?num(s.value)+'<span style="font-size:14px;color:var(--muted)"> / 100</span>':'—',s?`${esc(s.classification)} · ${delta(s.change7,' pts',0)} in 7 days`:'Fear & Greed Index',s?`${fresh('sentiment')?'As of':'Stale ·'} ${date(s.asOf)}`:'Daily reading',s?.history,'◌')}${stat('Dollar liquidity',m?money(m.value/1000,2)+'T':'—',m?`${delta(m.change30,'B')} USD over 4 weeks`:'Fed assets less Treasury cash and RRP',m?.asOf?`${m.status==='current'?'As of':'Stale ·'} ${date(m.asOf)}`:'Weekly proxy',m?.history,'⌁')}${stat('Corporate ownership',a?compact(a.total)+' BTC':'—',a?`${num(a.companies.length)} reported holders · ${percent(a.maxSupplyShare,2)} of 21M supply`:'Reported public-company holdings',a?`${fresh('adoption')?'Provider snapshot':'Stale snapshot'} · dates unknown`:'Ownership, not purchase flows',[],'◈')}</div>`;
}
function priceCard(detail=false) {
 const b=data('bitcoin'),spot=data('spot');
 return `<article class="card chart-card"><div class="card-head"><div><p class="kicker">BITCOIN / US DOLLAR</p><div class="chart-title-row"><p class="price">${money(spot?.price??b?.close)}</p>${b?`<span class="badge ${b.returns.day1>=0?'good':'bad'}">${percent(b.returns.day1,2,true)} daily close</span>`:''}</div>${spot?source('spot'):source('bitcoin')}</div><div class="chart-controls"><div class="segmented" aria-label="Price chart range">${[[90,'3M'],[365,'1Y'],[1460,'4Y'],[0,'ALL']].map(([n,l])=>`<button data-period="${n}" class="${state.period===n?'selected':''}" aria-pressed="${state.period===n}">${l}</button>`).join('')}</div><label class="toggle"><input id="log-scale" type="checkbox" ${state.log?'checked':''}>Log</label><label class="toggle"><input id="event-markers" type="checkbox" ${state.eventMarkers?'checked':''}>FOMC</label></div></div>${b?'<div id="price-chart" class="chart"></div>':empty('bitcoin','Bitcoin history is unavailable')}<div class="chart-legend"><span><i class="legend-dot" style="background:#cd783e"></i>Daily price</span><span><i class="legend-dot" style="background:#769277"></i>50-day average</span><span><i class="legend-dot" style="background:#768dac"></i>200-day average</span></div><div class="chart-foot">${b?`History: ${date(b.asOf)}${fresh('bitcoin')?'':' · STALE'} · ${esc(b.source)}. `:''}Returns use completed daily observations; the spot quote is separate. Hover or use the chart slider to inspect.${detail?' Weekly indicators use completed Sunday closes.':''}${state.eventMarkers?' Dotted markers show up to eight published FOMC decisions in range; dates do not establish causation.':''}</div></article>`;
}
function brief() {
 const b=data('bitcoin'),s=data('sentiment'),m=data('macro')?.metrics;
 let rows=[];
 if(b&&fresh('bitcoin'))rows.push(['Price & trend',`${trend(b)}. Bitcoin’s daily close is ${percent(Math.abs((b.close/b.ma200-1)*100))} ${b.close>=b.ma200?'above':'below'} its 200-day average.`]);
 else rows.push(['Price & trend',b?'Price history is stale. Treat the chart as historical context until the source refreshes.':'Daily price history will provide context on trend and momentum.']);
 if(m?.liquidity.status==='current'&&m?.real.status==='current'&&valid(m.liquidity.change30)&&valid(m.real.change30)) {
   const liq=m.liquidity.change30>=0,real=m.real.change30<=0;
   rows.push([liq===real?(liq?'A more supportive backdrop':'A tighter backdrop'):'Macro signals disagree',`The liquidity proxy ${liq?'rose':'fell'} ${money(Math.abs(m.liquidity.change30),1)}B over four weeks. Real yields ${real?'fell':'rose'} ${num(Math.abs(m.real.change30)*100,0)} basis points over 30 days.`]);
 } else rows.push(['Macro context',m?'Some macro inputs are delayed or unavailable. Their individual observation dates are shown in the Macro view.':'Liquidity and real yields provide different views of financial conditions.']);
 if(s&&fresh('sentiment'))rows.push(['Mood, with context',`${s.classification} (${s.value}/100). ${valid(s.change7)?`The index moved ${delta(s.change7,' points',0)} in seven days.`:''} Sentiment is context, not a timing signal.`]);
 else rows.push(['Mood, with context',s?'The sentiment reading is stale; it is excluded from the current assessment.':'Sentiment will appear when its daily feed is available.']);
 return `<article class="card brief-card"><div class="brief-heading"><p class="kicker">THE SHORT READ</p><span aria-hidden="true">✳</span></div><h2>What deserves attention</h2>${rows.map(([title,text],i)=>`<div class="brief-item"><span class="brief-number">0${i+1}</span><div><h3>${esc(title)}</h3><p>${esc(text)}</p></div></div>`).join('')}<p class="brief-bottom">A rules-based reading of the available data. These observations describe conditions; they do not predict returns.</p></article>`;
}
function macroPulse() {
 const m=data('macro')?.metrics;
 return `<article class="card"><div class="card-head"><h2>Macro pulse</h2><a class="fine-print" href="#macro">Details ↗</a></div>${[['real','Real yield'],['dollar','Broad US dollar'],['credit','Credit spread']].map(([key,label])=>signal(label,metricValue(m?.[key]),m?.[key]?.asOf?`${date(m[key].asOf)} · ${m[key].status==='current'?'current':'stale / unavailable'}`:'Waiting for source')).join('')}<p class="explanation">Watch the direction together. Lower real yields and a softer dollar can ease financial conditions; credit spreads reveal stress.</p></article>`;
}
function watchlist() {
 const cal=data('calendar');
 return `<article class="card"><div class="card-head"><h2>On the horizon</h2><span class="badge quiet">Official calendar</span></div>${cal?.events?.length?cal.events.slice(0,2).map(e=>`<div class="watch-item"><div class="date-box">${Number(e.date.slice(8))}<small>${new Date(e.date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',timeZone:'UTC'})} ${e.date.slice(2,4)}</small></div><div><h3><a href="${e.url}" target="_blank" rel="noreferrer">${e.title} ↗</a></h3><p>${esc(e.note)}</p></div></div>`).join(''):`<p class="fine-print">${state.feeds.calendar?'No upcoming dates available from the feed.':'Loading published FOMC dates…'}</p>`}<div class="signal-row"><a href="https://www.bls.gov/schedule/news_release/cpi.htm" target="_blank" rel="noreferrer">CPI release schedule ↗</a><span class="fine-print">BLS</span></div><div class="signal-row"><a href="https://www.bls.gov/schedule/news_release/empsit.htm" target="_blank" rel="noreferrer">Jobs report schedule ↗</a><span class="fine-print">BLS</span></div><p class="source-line">${cal?`Federal Reserve calendar · fetched ${date(state.feeds.calendar.retrievedAt)}${fresh('calendar')?'':' · STALE'}. `:''}Dates may change. Confirm with the official schedule.</p></article>`;
}
function demandCard(){const a=data('adoption');return `<article class="card"><div class="card-head"><h2>Ownership concentration</h2><a href="#adoption" class="fine-print">Explore ↗</a></div>${a?a.companies.slice(0,3).map(c=>signal(esc(c.name),`${compact(c.btc)} BTC`,esc(c.symbol))).join(''):empty('adoption','Treasury data unavailable')}<p class="explanation">${a?`${esc(a.companies[0].name)} represents ${percent(a.concentration)} of reported corporate holdings. `:''}Ownership is one dimension of adoption. It does not measure new buying or payment usage.</p></article>`;}
function overview(){return `${visitPanel()}${topStats()}${section('Market perspective','bitcoin','Open Bitcoin')}<div class="grid main-grid">${priceCard()}${brief()}</div>${section('Beyond the price')}<div class="grid grid-three">${macroPulse()}${demandCard()}${watchlist()}</div>${historicalContext()}`;}
function bitcoinView() {
 const b=data('bitcoin'),n=b?.network,s=data('sentiment');
 return `${priceCard(true)}${priceComparison()}${b?`<div class="returns-strip">${[['1D',b.returns.day1],['7D',b.returns.day7],['30D',b.returns.day30],['YTD',b.returns.ytd]].map(([label,value])=>`<span>${label} <strong class="${tone(value)}">${percent(value,2,true)}</strong></span>`).join('')}<small>Completed daily observations</small></div>`:''}${section('Trend & risk')}<div class="grid grid-four">${stat('200-week average',money(b?.ma200w),b?`${percent(valid(b.ma200w)?(b.close/b.ma200w-1)*100:null,1,true)} distance from daily close`:'Long-term trend context',b?.weeklyAsOf?date(b.weeklyAsOf):'Completed Sunday closes',b?.weekly)}${stat('Weekly RSI · 14',num(b?.weeklyRsi,1),'Momentum over completed weeks',b?.weeklyAsOf?`${fresh('bitcoin')?'As of':'Stale ·'} ${date(b.weeklyAsOf)}`:'0–100 oscillator')}${stat('30-day volatility',percent(b?.volatility),'Annualized daily return volatility',b?date(b.asOf):'Risk, not direction')}${stat('Drawdown',percent(b?.drawdown),'From the highest daily price in history',b?.peak?`Peak ${date(b.peak.date)}`:'Available source history')}</div>${b&&!fresh('bitcoin')?'<div class="disclosure">These indicators use stale price history. Check Sources before interpreting current conditions.</div>':''}${technicalContext()}${valuationPanel()}${section('Network fundamentals')}<div class="grid grid-four">${stat('Circulating supply',n?compact(n.supply?.value)+' BTC':'—',n?`${percent(n.supply?.value/21000000*100,2)} of the 21 million limit`:'No network observation available',n?.supply?.date?date(n.supply.date):'Coin Metrics',n?.supply?.history)}${stat('Hashrate · 30D mean',n&&valid(n.hashrate?.value)?num(n.hashrate.value/1e6)+' EH/s':'—',n?`${percent(n.hashrate?.change30,1,true)} vs 30 days earlier`:'Estimated mining computation',n?.hashrate?.date?date(n.hashrate.date):'Coin Metrics',n?.hashrate?.history)}${stat('Active addresses',compact(n?.addresses?.value),'30-day mean · addresses are not people',n?.addresses?.date?date(n.addresses.date):'Coin Metrics',n?.addresses?.history)}${stat('Daily transactions',compact(n?.transactions?.value),'30-day mean · includes non-payment activity',n?.transactions?.date?date(n.transactions.date):'Coin Metrics',n?.transactions?.history)}</div>${source('bitcoin',n?'Network activity does not measure unique users.':b?.networkError||'')}<div class="grid grid-two spaced"><article class="card"><div class="card-head"><h2>Market sentiment</h2>${badge(state.feeds.sentiment?.status)}</div>${s?`<div class="chart-title-row"><p class="price">${s.value}<span class="price-small muted"> / 100</span></p><span class="badge quiet">${esc(s.classification)}</span></div><div class="meter"><i class="meter-marker" style="left:${s.value}%"></i></div><div class="meter-labels"><span>Extreme fear</span><span>Extreme greed</span></div><div id="sentiment-chart" class="chart compact"></div>`:empty('sentiment')}${source('sentiment')}<p class="explanation">Fear & Greed combines price-related and behavioral inputs. It overlaps with momentum and is not an independent valuation measure.</p></article><article class="card"><div class="card-head"><h2>Reading the indicators</h2><span class="badge quiet">FIELD NOTES</span></div>${signal('50D / 200D averages','Trend','Price relative to recent daily history.')}${signal('200W average','Long horizon','An average of 200 completed Sunday observations.')}${signal('RSI','Momentum','Above 70 or below 30 marks strong momentum, not an automatic reversal.')}${signal('Volatility & drawdown','Risk','How much price moves and how far it sits below its historical peak.')}<p class="explanation">MVRV and derived realized price add an on-chain valuation lens above. Their source dates can differ from the live spot quote. Explore Power Law and stock-to-flow in <a href="#models">Price models</a>.</p></article></div>`;
}
function adoptionView() {
 const a=data('adoption');
 return `${etfPanel()}${section('Corporate ownership')}<div class="grid grid-three">${stat('Reported corporate BTC',a?num(a.total)+' BTC':'—','Provider aggregate of corporate holdings','Reporting dates unavailable')}${stat('Share of maximum supply',percent(a?.maxSupplyShare,2),'Reported holdings ÷ 21 million BTC','Maximum supply, not circulating float')}${stat('Largest holder’s share',percent(a?.concentration,1),a?esc(a.companies[0].name):'Corporate concentration','Share of reported corporate holdings')}</div><div class="disclosure">${a?esc(a.note):'Corporate holdings reflect reported ownership. Individual filing dates may differ, and the provider may revise its coverage.'} This is an investment-adoption proxy; payment adoption and ETF holdings are separate.</div><article class="card"><div class="card-head"><div><h2>Corporate Bitcoin holdings</h2>${source('adoption')}</div><label><span class="kicker" style="display:block;margin-bottom:6px">FIND A COMPANY</span><input id="company-search" class="search" type="search" placeholder="Name or ticker…" value="${esc(state.search)}"></label></div><div id="companies">${companyTable()}</div></article>${adoptionHistoryPanel()}<div class="grid grid-three spaced"><article class="card link-card"><p class="kicker">INSTITUTIONAL DEMAND</p><h2>ETF flows</h2><span class="badge warn">External source</span><p>Use reported net flows to assess new fund demand. Changes in dollar assets under management also include price moves. Import reported sessions above to analyze flows locally.</p><a href="https://farside.co.uk/bitcoin-etf-flow-all-data/" target="_blank" rel="noreferrer">Open Farside ETF flows ↗</a></article><article class="card link-card"><p class="kicker">HOLDINGS VERIFICATION</p><h2>Go to the issuer</h2><span class="badge quiet">Primary disclosure</span><p>Fund holdings show owned BTC, not daily buying. The issuer’s reported quantity and as-of date provide a useful cross-check.</p><a href="https://www.ishares.com/us/products/333011/ishares-bitcoin-trust" target="_blank" rel="noreferrer">View IBIT holdings ↗</a></article><article class="card link-card"><p class="kicker">ADOPTION BEYOND OWNERSHIP</p><h2>Network participation</h2><span class="badge quiet">Daily observations</span><p>Activity on the base layer adds context. Addresses can be shared or numerous per person; transactions also include exchange and non-payment activity.</p><a href="#bitcoin">Explore network fundamentals ↗</a></article></div>`;
}
function companyTable() {
 const a=data('adoption');if(!a)return empty('adoption','Corporate holdings are unavailable');
 const found=a.companies.filter(c=>`${c.name} ${c.symbol}`.toLowerCase().includes(state.search.toLowerCase()));
 const rows=state.allCompanies?found:found.slice(0,12);
 return `<div class="table-wrap"><table><thead><tr><th>Company</th><th>Country</th><th class="numeric">Bitcoin held</th><th class="numeric">Share of reported total</th></tr></thead><tbody>${rows.map(c=>`<tr><td><span class="company-name">${esc(c.name)}</span><span class="company-ticker">${esc(c.symbol)}</span></td><td>${esc(c.country)}</td><td class="numeric">${num(c.btc,1)} BTC</td><td class="numeric">${percent(c.btc/a.total*100,2)}<div class="holding-bar"><i style="width:${Math.min(100,c.btc/a.total*100)}%"></i></div></td></tr>`).join('')||'<tr><td colspan="4">No companies match this search.</td></tr>'}</tbody></table></div><div class="table-footer"><span>${rows.length} of ${found.length} matching holders · excludes zero holdings</span>${found.length>12?`<button class="button" id="show-companies">${state.allCompanies?'Show fewer':'Show all holders'}</button>`:''}</div>`;
}
function metricValue(m) {if(!valid(m?.value))return '—';return m.unit==='billions'?m.value>=1000?`${money(m.value/1000,2)}T`:`${money(m.value,1)}B`:m.unit==='percent'||m.unit==='yoy'?percent(m.value,2):num(m.value,2);}
function macroCard(key) {
 const m=data('macro')?.metrics?.[key];if(!m)return `<article class="card macro-card"><p class="kicker">${esc(key)}</p><p class="macro-value skeleton">—</p><p class="fine-print">Connecting to FRED…</p></article>`;
 const suffix=m.unit==='percent'||m.unit==='yoy'?' pp':m.unit==='billions'?'B':' pts';
 const comparison=key==='liquidity'?'4 weeks':m.maxAge>30?'previous month':'30 days';
 return `<article class="card macro-card"><div class="metric-top"><p class="kicker">${esc(m.name)}</p>${badge(m.status)}</div><p class="macro-value">${metricValue(m)}${m.unit==='yoy'?'<span class="price-small muted"> YoY</span>':''}</p><p class="macro-stat"><strong>${delta(m.change30,suffix,2)}</strong> vs ${comparison}</p><p class="fine-print">${esc(m.description)}</p>${contextHtml(m.history,m.value,m.asOf,v=>m.unit==='billions'?money(v/1000,2)+'T':m.unit==='index'?num(v,1):percent(v,2))}<div class="stat-bottom"><span>${m.asOf?date(m.asOf):'No observation'}</span>${spark(m.history)}</div><div class="source-line"><a href="${esc(m.url)}" target="_blank" rel="noreferrer">${esc(m.source)}${m.id?` · ${m.id}`:''} ↗</a></div></article>`;
}
function macroView() {
 const m=data('macro')?.metrics,current=m?.[state.macroMetric];
 return `${contextControls()}<article class="card chart-card"><div class="card-head"><div><p class="kicker">MACRO EXPLORER</p><h2 style="margin-top:9px">${esc(current?.name||'Dollar liquidity proxy')}</h2><div class="chart-title-row"><p class="price">${metricValue(current)}</p>${current?badge(current.status):''}</div></div><label><span class="kicker" style="display:block;margin-bottom:8px">INDICATOR</span><select class="select" id="macro-select">${['liquidity','real','nominal','dollar','credit','curve','inflation','unemployment','m2'].map(k=>`<option value="${k}" ${k===state.macroMetric?'selected':''}>${esc(m?.[k]?.name||k)}</option>`).join('')}</select></label></div><div class="segmented macro-period" aria-label="Macro chart period">${[[365,'1Y'],[1095,'3Y'],[1825,'5Y'],[0,'ALL']].map(([n,l])=>`<button data-macro-period="${n}" class="${state.macroPeriod===n?'selected':''}" aria-pressed="${state.macroPeriod===n}">${l}</button>`).join('')}</div>${current?.history?.length?'<div id="macro-chart" class="chart"></div>':empty('macro','This macro series is unavailable')}<div class="chart-foot">${esc(current?.description||'Fed assets less Treasury cash and reverse repo, aligned to weekly dates.')} ${current?.asOf?`Latest observation: ${date(current.asOf)}.`:''}</div></article>${section('Liquidity & money')}<div class="grid grid-four">${['liquidity','fed','tga','rrp'].map(macroCard).join('')}</div>${section('Rates, dollar & credit')}<div class="grid grid-three">${['real','nominal','dollar','credit','curve','twoYear'].map(macroCard).join('')}</div>${section('The real economy')}<div class="grid grid-three">${['inflation','unemployment','m2'].map(macroCard).join('')}</div><div class="disclosure">Monthly series are dated to the month they measure, not their release day. Data can be revised. The liquidity proxy is one US monetary lens; no single series determines Bitcoin’s price.</div>`;
}
// Research views share the same formatting and source conventions as the original dashboard.
function readVisit(){try{const saved=JSON.parse(localStorage.getItem('macro.visit.v1'));return saved?.version===1&&saved.items&&Number.isFinite(Date.parse(saved.at))?saved:null;}catch{return null;}}
let visitBaseline=readVisit(),visitStorageAvailable=true,visitReady=false;
function visitSnapshot(){
 const items={};
 function add(key,label,value,unit,feed,asOf,source,kind){items[key]={label,value,unit,status:state.feeds[feed]?.status||'unavailable',asOf:asOf||null,source:source||feed,kind};}
 const b=data('bitcoin'),s=data('sentiment'),a=data('adoption'),v=data('valuation'),e=data('etf');
 add('price','Bitcoin daily close',b?.close,'USD','bitcoin',b?.asOf,b?.source);
 add('trend','Bitcoin trend',b?trend(b):null,'','bitcoin',b?.asOf,b?.source,'category');
 add('sentiment','Fear & Greed',s?.value,'points','sentiment',s?.asOf,s?.source);
 add('corporate','Reported corporate BTC',a?.total,'BTC','adoption',null,a?.source);
 add('mvrv','MVRV',v?.mvrv,'×','valuation',v?.asOf,v?.source);
 if(e)add('etf','Latest reported ETF session',e.latest?.status==='complete'?e.latest.total:null,'USD','etf',e.asOf,e.source);
 for(const key of ['liquidity','real','dollar','credit']){const m=data('macro')?.metrics?.[key];items[key]={label:m?.name||key,value:m?.value,unit:m?.unit==='billions'?'USD B':m?.unit==='percent'?'pp':'points',status:m?.status||'unavailable',asOf:m?.asOf||null,source:m?.id||key};}
 return {version:1,at:new Date().toISOString(),items};
}
function saveVisit(){try{localStorage.setItem('macro.visit.v1',JSON.stringify(visitSnapshot()));visitStorageAvailable=true;}catch{visitStorageAvailable=false;}}
function visitPanel(){
 const snapshot=visitSnapshot(),changes=Research.visitChanges(visitBaseline,snapshot);
 if(visitReady&&visitBaseline&&!changes.length&&visitStorageAvailable)return '';
 const labels={current:'current',stale:'delayed',unavailable:'unavailable'};
 const renderChange=c=>{
   if(c.kind==='availability')return `<div class="visit-change"><strong>${esc(c.label)}</strong><span>${esc(labels[c.from]||c.from)} → ${esc(labels[c.to]||c.to)}</span></div>`;
   if(c.kind==='source')return `<div class="visit-change"><strong>${esc(c.label)}</strong><span>Source changed; values not compared</span></div>`;
   if(c.kind==='category')return `<div class="visit-change"><strong>${esc(c.label)}</strong><span>${esc(c.from)} → ${esc(c.to)}</span></div>`;
   const value=c.unit==='USD'?delta(c.delta,' USD',2):delta(c.delta,` ${c.unit}`,c.unit==='BTC'?1:2);
   return `<div class="visit-change"><strong>${esc(c.label)}</strong><span>${value}${c.revised?' <small>same-date revision</small>':''}${c.key==='corporate'?' <small>provider snapshot change</small>':''}</span></div>`;
 };
 return `<article class="card visit-panel"><div class="card-head"><div><p class="kicker">YOUR RESEARCH CHECK-IN</p><h2>Since your last visit</h2><p class="fine-print">${visitBaseline?`Compared with your browser snapshot from ${date(visitBaseline.at)} at ${new Date(visitBaseline.at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}.`:'Your first visit establishes a baseline. Come back later to see what changed.'}</p></div><button class="button" id="mark-reviewed" ${!visitReady?'disabled':''}>Mark reviewed</button></div>${!visitReady?'<p class="fine-print">Waiting for the current check-in to finish…</p>':visitBaseline?changes.length?`<div class="visit-grid">${changes.map(renderChange).join('')}</div>`:'<p class="fine-print">No changes in the tracked readings since that snapshot.</p>':'<p class="fine-print">Baseline saved for this browser. Refreshes during this visit keep the comparison fixed.</p>'}${!visitStorageAvailable?'<p class="import-error">Browser storage is unavailable. This comparison cannot persist across visits.</p>':''}<p class="source-line">Only current, comparable readings are compared. Delayed data appears as a source-status change. Mark reviewed starts a new comparison.</p></article>`;
}
function contextHtml(rows,value,asOf,format= num,minSamples=20){
 const ctx=Research.context(rows||[],value,{days:state.contextDays,asOf,minSamples});
 if(!ctx)return '<p class="context-caption">Historical context needs more observations.</p>';
 const rank=Math.round(ctx.percentile),label=rank>=90?'Upper historical range':rank<=10?'Lower historical range':'Within historical range';
 return `<div class="context-block"><div class="context-caption"><strong>${rank}th percentile</strong><span>${label}</span></div><div class="context-track"><i style="left:${Math.min(99,Math.max(1,rank))}%"></i></div><div class="context-caption"><span>10th: ${format(ctx.p10)}</span><span>Median: ${format(ctx.median)}</span><span>90th: ${format(ctx.p90)}</span></div><p class="context-dates">${ctx.count} observations · ${date(ctx.from)}–${date(ctx.to)}</p></div>`;
}
function contextControls(){return `<div class="context-controls"><span class="kicker">HISTORICAL CONTEXT</span><div class="segmented" aria-label="Historical context period">${[[365,'1Y'],[1095,'3Y'],[1825,'5Y']].map(([n,l])=>`<button data-context="${n}" class="${state.contextDays===n?'selected':''}" aria-pressed="${state.contextDays===n}">${l}</button>`).join('')}</div><span class="fine-print">Percentile describes history, not a forecast.</span></div>`;}
function historicalContext(){
 const s=data('sentiment'),v=data('valuation'),m=data('macro')?.metrics;
 const items=[['Fear & Greed',s?.value,s?.history,s?.asOf,v=>num(v,0)],['MVRV',v?.mvrv,v?.history?.map(p=>({date:p.date,value:p.mvrv})),v?.asOf,v=>num(v,2)+'×'],['Real yield',m?.real?.value,m?.real?.history,m?.real?.asOf,v=>percent(v,2)]];
 return `${section('How unusual are today’s readings?')}${contextControls()}<div class="grid grid-three">${items.map(([name,value,rows,asOf,format])=>`<article class="card"><p class="kicker">${name}</p><p class="macro-value">${valid(value)?format(value):'—'}</p>${contextHtml(rows,value,asOf,format)}<p class="source-line">As of ${date(asOf)} · Check source health for delays.</p></article>`).join('')}</div>`;
}
function technicalContext(){
 const b=data('bitcoin'),c=b?.context;
 const items=[['Distance from 200D mean',c?.distance,v=>percent(v,1)],['Weekly RSI',c?.weeklyRsi,v=>num(v,1)],['Realized volatility',c?.volatility,v=>percent(v,1)]];
 return `${section('Trend in historical context')}${contextControls()}<div class="grid grid-three">${items.map(([label,rows,format])=>`<article class="card"><p class="kicker">${label}</p>${contextHtml(rows,rows?.at(-1)?.value,rows?.at(-1)?.date,format)}<p class="source-line">${b?`${esc(b.source)} · ${fresh('bitcoin')?'Current history':'Delayed history'}`:'Awaiting source'}</p></article>`).join('')}</div>`;
}
function valuationPanel(){
 const v=data('valuation');
 return `${section('On-chain valuation')}${contextControls()}<div class="grid grid-two"><article class="card chart-card"><div class="card-head"><div><p class="kicker">PRICE & AGGREGATE COST BASIS</p><h2>Realized price</h2></div>${badge(state.feeds.valuation?.status)}</div>${v?`<div class="chart-title-row"><p class="price">${money(v.realizedPrice)}</p><span class="badge quiet">Derived</span></div><div id="valuation-chart" class="chart"></div><div class="chart-legend"><span><i class="legend-dot" style="background:#cd783e"></i>Daily price</span><span><i class="legend-dot" style="background:#75916f"></i>Derived realized price</span></div>`:empty('valuation','Valuation feed unavailable')}${source('valuation')}<p class="explanation">Same-day price ÷ MVRV. Realized capitalization values coins when they last moved; it approximates aggregate cost basis and is not a guaranteed price floor.</p></article><article class="card"><div class="card-head"><h2>MVRV</h2><span class="badge quiet">Market / realized value</span></div><p class="price">${v?num(v.mvrv,2)+'×':'—'}</p>${contextHtml(v?.history?.map(p=>({date:p.date,value:p.mvrv})),v?.mvrv,v?.asOf,x=>num(x,2)+'×')}<div id="mvrv-chart" class="chart compact"></div><p class="explanation">1× means market value equals realized value. Historical extremes provide context; they are not automatic buy or sell thresholds.</p></article></div>`;
}
function etfPanel(){
 const e=data('etf'),latest=e?.latest;
 const usd=v=>valid(v)?`${v<0?'−':v>0?'+':''}$${compact(Math.abs(v))}`:'—';
 return `${section('Institutional demand')}<article class="card"><div class="card-head"><div><p class="kicker">REPORTED US SPOT BITCOIN ETF FLOWS</p><h2>Follow net fund demand</h2></div><span class="badge ${e?'quiet':'warn'}">${e?'Imported dataset':'Source needed'}</span></div>${e?`<div class="grid grid-three etf-totals"><div><p class="kicker">${latest.status==='complete'?'LATEST REPORTED SESSION':'PARTIAL / PENDING SESSION'}</p><p class="macro-value">${usd(latest.total)}</p><p class="fine-print">${date(e.asOf)} · ${latest.reported}/${latest.expected} funds · ${esc(latest.status)}</p></div><div><p class="kicker">LAST 5 SUPPLIED SESSIONS</p><p class="macro-value">${usd(e.flow5)}</p><p class="fine-print">${valid(e.flow5)?'All five rows complete; stable fund count':'Needs five complete rows with a stable fund count'}</p></div><div><p class="kicker">LAST 20 SUPPLIED SESSIONS</p><p class="macro-value">${usd(e.flow20)}</p><p class="fine-print">${valid(e.flow20)?'All twenty rows complete; stable fund count':'Needs twenty complete rows with a stable fund count'}</p></div></div>${etfCandleControls()}${source('etf')}<p class="fine-print">Universe: ${esc(e.universe)}. ${esc(e.coverage)}</p><details class="etf-sessions"><summary>Reporting completeness by session</summary><div class="table-wrap"><table><thead><tr><th>Date</th><th class="numeric">Net USD</th><th>Funds</th><th>Status</th></tr></thead><tbody>${e.history.slice(-20).reverse().map(p=>`<tr><td>${date(p.date)}</td><td class="numeric">${valid(p.total)?money(p.total,0):'—'}</td><td>${p.reported}/${p.expected}</td><td>${esc(p.status)}</td></tr>`).join('')}</tbody></table></div></details>`:'<p class="fine-print">Import reported ETF flows to populate the chart. No subscription is configured.</p>'}${!e?etfCandleControls():''}<details id="etf-import-details" class="etf-import" ${!e?'open':''}><summary>${e?'Replace imported ETF dataset':'Import a provider CSV'}</summary><form id="etf-import-form"><div class="import-fields"><label>Source name<input name="source" required maxlength="100" placeholder="Provider or issuer name" value="${esc(e?.source||'')}"></label><label>Original source URL<input name="url" type="url" required placeholder="https://…" value="${esc(e?.url||'')}"></label><label>Fund universe<input name="universe" required maxlength="160" placeholder="e.g. 11 US spot Bitcoin funds" value="${esc(e?.universe||'')}"></label><label>CSV export<input name="file" type="file" accept=".csv,text/csv" required></label></div><p class="fine-print">Columns: date, net_flow_usd, reported_funds, expected_funds, status. USD amounts are dollars, not millions. Status: complete, partial, or pending. Include every supplied session; leave unknown totals blank. Import replaces the displayed series and preserves detected revisions.</p><div class="import-actions"><button class="button" type="submit">Validate & import</button><a href="etf-template.csv" download>Download column template ↗</a><a href="https://farside.co.uk/bitcoin-etf-flow-all-data/" target="_blank" rel="noreferrer">Farside source table ↗</a></div><p id="import-message" role="status" class="fine-print"></p></form></details></article>`;
}
function adoptionHistoryPanel(){
 const h=state.archive?.adoption;
 return `${section('Corporate ownership through time')}<article class="card"><div class="card-head"><div><h2>Reported holdings history</h2><p class="fine-print">${h?.startedAt?`Tracking since ${date(h.startedAt)} · ${h.snapshots.length} saved snapshots`:'History starts with the first successful retrieval.'}</p></div><span class="badge quiet">Provider snapshots</span></div>${h?.snapshots?.length>1?'<div id="adoption-history-chart" class="chart compact"></div>':'<p class="fine-print">The first snapshot establishes a baseline. A timeline appears after another observation; no historical purchases are invented.</p>'}${h?.changes?.length?`<div class="table-wrap"><table><thead><tr><th>Detected</th><th>Company</th><th>Change type</th><th class="numeric">BTC difference</th></tr></thead><tbody>${h.changes.flatMap(event=>event.changes.map(c=>({...c,at:event.at}))).slice(0,25).map(c=>`<tr><td>${date(c.at)}</td><td>${esc(c.name)}</td><td>${c.type==='added'?'New to provider coverage':c.type==='removed'?'Removed from coverage':'Reported balance changed'}</td><td class="numeric">${c.type==='changed'?delta(c.delta,' BTC',2):'Not comparable'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="source-line">No provider holding changes have been observed yet.</p>'}<p class="explanation">A change can reflect a new filing, correction, reclassification, or coverage change. It is not labeled a purchase without a dated primary disclosure. Individual filing dates are not supplied by this feed.</p>${h?.storageError?`<p class="import-error">${esc(h.storageError)}</p>`:''}</article>`;
}
function reliabilityPanel(){
 const a=state.archive;
 const events=(a?.feeds||[]).flatMap(f=>f.events.map(e=>({...e,key:f.key,source:f.source}))).sort((x,y)=>y.at.localeCompare(x.at)).slice(0,15);
 const failures=(a?.health||[]).filter(h=>h.error);
 return `${section('Observation archive & revisions')}<article class="card"><div class="card-head"><div><h2>What changed at the source</h2><p class="fine-print">Successful observations persist on this computer. Failed refreshes never overwrite them.</p></div><span class="badge quiet">${a?.feeds?.reduce((n,f)=>n+f.observations,0)||0} dated observations</span></div>${a?.storageError?`<p class="import-error">${esc(a.storageError)}</p>`:''}${failures.map(f=>`<p class="disclosure">${esc(f.key)} · Last attempt ${date(new Date(f.lastAttempt).toISOString())}: ${esc(f.error)}</p>`).join('')}${events.length?events.map(e=>`<details class="revision-item"><summary>${date(e.at)} · ${esc(e.key)} · ${e.type==='revision'?`${e.count} historical observations revised`:e.type==='source-change'?'Provider changed':'Corporate snapshot changed'}</summary><p class="fine-print">${e.type==='source-change'?`${esc(e.from)} → ${esc(e.to)}`:e.type==='snapshot-change'?'Changes in a reported snapshot do not establish purchases.':(e.changes||[]).map(c=>`${date(c.date)}: ${esc(JSON.stringify(c.before))} → ${esc(JSON.stringify(c.after))}`).join('<br>')}</p></details>`).join(''):'<p class="fine-print">No revisions have been detected since tracking began. New dates are observations, not revisions.</p>'}<p class="source-line">Revision history retains the latest 200 revision batches per feed. Raw observed dates and corporate snapshots are retained. “Delayed observation” means an old publication date; “refresh failed” means the request itself failed.</p></article>`;
}

const METHODS=[
 ['Historical context & last visit','Percentiles use observations from the selected trailing calendar window, ending at the displayed observation date. Rank counts values below the current reading plus half of equal values. At least 20 observations are required; exact coverage dates and sample counts are displayed. Percentiles are descriptions, not signals. Last-visit snapshots stay in this browser’s local storage; refreshes do not move the comparison baseline. Mark reviewed explicitly starts a new baseline. Source changes, stale readings and unavailable values are not compared numerically.'],
 ['Valuation derivation','Coin Metrics defines CapMVRVCur as current market capitalization divided by realized capitalization. PriceUSD / CapMVRVCur therefore gives realized capitalization per circulating coin. Both inputs must be positive and exist on the same completed daily row. Missing days are not forward-filled. Coin movement is not necessarily a sale, so realized value is only an aggregate cost-basis approximation.'],
 ['Bitcoin history, spot & returns','Coin Metrics daily prices are the primary historical series; Blockchain.com provides a price-only fallback. A refresh uses one provider’s complete history, never spliced daily sources. Today’s incomplete daily observation is excluded. Spot is fetched independently from Coinbase, with CoinGecko as fallback; Coinbase supplies no observation timestamp, so its time is labeled “fetched.” Returns compare completed daily observations on exact calendar dates. YTD uses the prior December 31 close. Missing history stays unavailable.'],
 ['Moving averages, RSI & volatility','50D and 200D means require consecutive daily observations. The 200W mean uses 200 consecutive completed Sunday observations. Weekly RSI uses Wilder’s smoothing over 14 weekly changes; a gap resets its warm-up. Thirty-day realized volatility uses the sample standard deviation of 30 daily log returns, annualized by √365. Drawdown compares the latest daily observation with the highest daily observation in the available history; it is not an intraday all-time-high measure.'],
 ['Network fundamentals','Supply is the latest Coin Metrics circulating-supply observation. Hashrate (converted from TH/s to EH/s), active addresses and transactions are trailing 30-day arithmetic means. Hashrate is an estimate, not a direct measurement. Addresses are not unique people, and transactions do not equal retail payments. These are base-layer activity indicators, not comprehensive adoption measures.'],
 ['Dollar liquidity & macro changes','The liquidity proxy is WALCL / 1,000 − RRPONTSYD − WDTGAL / 1,000, expressed in billions of USD. WALCL and WDTGAL are Wednesday levels in millions; RRP is daily in billions. We match the same Wednesday and permit only RRP to carry back up to three days for holidays. The change is four calendar weeks. Other daily series compare to 30 calendar days earlier with limited holiday tolerance. Monthly changes use the prior monthly observation. CPI inflation compares the same month one year earlier. The yield curve uses matching observation dates.'],
 ['Sentiment & the short read','Alternative.me’s Fear & Greed index runs from 0 to 100. Its daily history and seven-day point change provide context; several components already reflect price action. The short read uses transparent comparisons of price versus its 200-day mean, four-week liquidity change and 30-day real-yield change. Only current data contributes. The summary is deterministic, not an AI forecast or validated trading model.'],
 ['Corporate ownership & adoption coverage','CoinGecko supplies aggregate and per-company Bitcoin holdings. The endpoint does not provide individual filing dates, so “fetched” never means “holdings as of today.” Maximum-supply share divides holdings by 21 million; concentration divides the largest holder by the provider aggregate. The list excludes zero holdings and does not independently verify filings. No purchase flow or growth rate is inferred from a snapshot. ETF analysis accepts a sourced aggregate CSV with declared fund coverage. Rolling totals require complete rows and a stable expected fund count; missing session dates cannot be independently detected. Imported observations remain labeled as imports.'],
 ['Freshness, caches & missing data','Sources are cached independently: spot for one minute, Bitcoin history for six hours, sentiment and FRED for one hour, corporate holdings for twelve hours, and the calendar for one day. Expired saved data is shown as stale while a background refresh runs. Refresh data waits for a new attempt. A failed request never overwrites the last good observation. We also mark delayed daily Bitcoin/sentiment data (over three days), weekly macro (over ten days), daily macro (over five to seven days), and monthly macro (over 65–75 days). “Current” is relative to that cadence, not a guarantee against revisions. Treasury reporting dates remain unknown.'],
 ['Calendar, models & deliberate omissions','FOMC decision dates come from the Federal Reserve’s published calendar, with the final day of each meeting shown. Tentative dates can change. CPI and jobs reports link to BLS schedules because automated access was unavailable; no dates are guessed. The prior stock-to-flow projection was removed from the daily experience. MVRV comes from Coin Metrics; realized price is derived from the same row’s PriceUSD divided by CapMVRVCur. Derivatives positioning and automated ETF flows still require verified access.']
];
function sourcesView() {
 const names={supply:'S2F supply history',spot:'Spot price',bitcoin:'Bitcoin & network',sentiment:'Fear & Greed',adoption:'Corporate holdings',calendar:'FOMC calendar',valuation:'MVRV & realized price',etf:'Reported ETF flows'};
 const rows=Object.entries(names).map(([key,name])=>{const f=state.feeds[key],d=f?.data;return `<div class="source-item"><div><a ${d?`href="${esc(d.url)}" target="_blank" rel="noreferrer"`:''}>${name} ${d?'↗':''}</a><p>${esc(d?.source||(key==='etf'?'Import a provider CSV in Adoption':'Waiting for source'))}</p></div><div>${f?.reason==='not-connected'?'<span class="badge quiet">Awaiting import</span>':badge(f?.status)}${f?.refreshing?'<p>Refresh in progress</p>':''}</div><div><p>${d?.asOf?`${d.timestampKind==='retrieved'?'Fetched':'Observation'}: ${date(d.asOf)}`:key==='adoption'?'Reporting dates: not supplied':'Published schedule'}<br>Retrieved: ${f?.retrievedAt?date(f.retrievedAt):'Not yet available'}${f?.observationDelayed?'<br>Observation is older than its expected publication cadence.':''}${f?.error?`<br>${esc(f.error)}`:''}</p></div></div>`;});
 const macro=data('macro')?.metrics;
 if(macro)for(const m of Object.values(macro))rows.push(`<div class="source-item"><div><a href="${esc(m.url)}" target="_blank" rel="noreferrer">${esc(m.name)} ↗</a><p>${esc(m.source)} ${esc(m.id||'')}</p></div><div>${badge(m.status)}</div><div><p>Observation: ${m.asOf?date(m.asOf):'Unavailable'}${m.observationDelayed?'<br>Observation is older than its expected publication cadence.':''}${m.error?`<br>Refresh failed: ${esc(m.error)}`:''}</p></div></div>`);
 return `${reliabilityPanel()}${section('Current source health')}<article class="card"><div class="card-head"><h2>Source health</h2><span class="badge quiet">No synthetic data</span></div>${rows.join('')}</article>${section('How to read the dashboard')}<article class="card methods">${METHODS.map(([title,text])=>`<details><summary>${title}</summary><p>${esc(text)}</p></details>`).join('')}</article><div class="disclosure">Designed for understanding market conditions. Indicators describe different timeframes and can disagree. Figures may be delayed, incomplete or revised; consult the linked primary disclosures before acting on a specific number.</div>`;
}
function render() {
 const openDetails=[...document.querySelectorAll('.methods details')].map(d=>d.open);
 const openIds=[...document.querySelectorAll('details[id][open]')].map(d=>d.id);
 const [eyebrow,title,subtitle]=PAGES[state.view];$('eyebrow').textContent=eyebrow;$('page-title').textContent=title;$('page-subtitle').textContent=subtitle;$('breadcrumb').textContent=state.view==='macro'?'MACRO LANDSCAPE':state.view.toUpperCase();
 document.querySelectorAll('[data-view]').forEach(a=>{const active=a.dataset.view===state.view;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('view').innerHTML=({overview,bitcoin:bitcoinView,adoption:adoptionView,macro:macroView,models:modelsView,narratives:narrativesView,sources:sourcesView}[state.view])();
 document.querySelectorAll('.methods details').forEach((d,i)=>d.open=Boolean(openDetails[i]));
 openIds.forEach(id=>{if($(id))$(id).open=true;});
 renderCharts();renderStatus();MetricHelp.mount($('view'));
}
function renderStatus() {
 let current=0,stale=0,missing=0,loading=0,unconnected=0;
 for(const key of FEEDS){const f=state.feeds[key];if(!f){loading++;continue;}if(f.reason==='not-connected'){unconnected++;continue;}if(key==='macro'&&f.data){const statuses=Object.values(f.data.metrics).map(m=>m.status);if(statuses.every(s=>s==='current'))current++;else if(statuses.some(s=>s!=='unavailable'))stale++;else missing++;}else if(f.status==='current')current++;else if(f.status==='stale')stale++;else missing++;}
 const parts=[`${current} / ${FEEDS.length-unconnected} connected feeds current`,...(stale?[`${stale} delayed or partial`]:[]),...(missing?[`${missing} unavailable`]:[]),...(loading?[`${loading} connecting`]:[]),...(unconnected?['ETF import not configured']:[])];
 $('feed-status').innerHTML=`<span class="status-dot ${stale||missing||loading?'warn':''}"></span>${parts.join(' <span aria-hidden="true">·</span> ')}<a class="status-link" href="#sources">Observation dates & source health ↗</a>${state.view==='overview'?`<span class="last-refreshed" title="Time this dashboard last finished checking its data feeds. Individual observations may be older; source health is shown separately.">Last refreshed: ${state.lastRefreshed?`<time datetime="${state.lastRefreshed}">${new Date(state.lastRefreshed).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',second:'2-digit',timeZoneName:'short'})}</time>`:'Waiting for first refresh…'}</span>`:''}`;
}
// SVG charts keep the app independent of external scripts. The range input also exposes data to keyboard users.
function drawChart(id,rows,series,{log=false,format=money,tooltipFormat=format,domain=null,compactChart=false,events=[],bars=false}={}) {
 const el=$(id);if(!el||!rows.length)return;
 const W=Math.max(260,el.clientWidth),H=compactChart?180:260,L=8,R=65,T=14,B=27;
 const values=rows.flatMap(p=>series.map(s=>p[s.key])).filter(v=>valid(v)&&(!log||v>0));
 if(!values.length){el.innerHTML='<div class="empty">No observations for this indicator</div>';return;}
 const transform=v=>log?Math.log10(v):v;
 let lo=domain?domain[0]:Math.min(...values,...(bars?[0]:[])),hi=domain?domain[1]:Math.max(...values,...(bars?[0]:[]));
 if(lo===hi){lo-=Math.abs(lo)*.05||1;hi+=Math.abs(hi)*.05||1;}
 if(log)lo=Math.max(lo,Math.min(...values.filter(v=>v>0))*.9);
 let min=transform(lo),max=transform(hi);if(!domain){const pad=(max-min)*.08;min-=pad;max+=pad;}
 const first=Date.parse(rows[0].date),end=Date.parse(rows.at(-1).date),span=end-first||1;
 const x=i=>L+(Date.parse(rows[i].date)-first)/span*(W-L-R), y=v=>T+(1-(transform(v)-min)/(max-min))*(H-T-B);
 const ticks=Array.from({length:4},(_,i)=>{const t=min+(max-min)*i/3;return log?10**t:t;});
 const grid=ticks.map(v=>`<line class="chart-grid" x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}"/><text class="chart-axis" x="${W-R+10}" y="${y(v)+4}">${esc(format(v))}</text>`).join('');
 const dates=[...new Set(Array.from({length:5},(_,i)=>Math.round(i*(rows.length-1)/4)))].map((i,j,a)=>`<text class="chart-axis" x="${x(i)}" y="${H-6}" text-anchor="${j===0?'start':j===a.length-1?'end':'middle'}">${new Date(rows[i].date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',year:'2-digit',timeZone:'UTC'})}</text>`).join('');
 const paths=bars?rows.map((p,i)=>{const v=p[series[0].key];if(!valid(v))return '';const zero=y(0);return `<rect x="${x(i)-Math.max(2,(W-L-R)/rows.length*.3)}" y="${Math.min(zero,y(v))}" width="${Math.max(3,(W-L-R)/rows.length*.6)}" height="${Math.max(1,Math.abs(zero-y(v)))}" fill="${v>=0?'#75916f':'#b75e50'}"/>`;}).join(''):series.map(s=>{let started=false;const d=rows.map((p,i)=>{const v=p[s.key];if(!valid(v)||(log&&v<=0)){started=false;return '';}const cmd=started?'L':'M';started=true;return `${cmd}${x(i).toFixed(2)},${y(v).toFixed(2)}`;}).join(' ');return `<path d="${d}" fill="none" stroke="${s.color}" stroke-width="${s.width||1.8}" stroke-dasharray="${s.dash||''}" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>`;}).join('');
 const visibleEvents=events.filter(e=>e.date>=rows[0].date&&e.date<=rows.at(-1).date).slice(-8);
 const markers=visibleEvents.map(e=>{const xx=L+(Date.parse(e.date)-first)/span*(W-L-R);return `<g><title>${esc(e.title)} · ${date(e.date)}</title><line x1="${xx}" x2="${xx}" y1="${T}" y2="${H-B}" stroke="#9b9ba8" stroke-dasharray="2 5" opacity=".5"/><circle cx="${xx}" cy="${T}" r="3" fill="#8a8299"/></g>`;}).join('');
 el.innerHTML=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="${esc(series.map(s=>s.name).join(', '))} from ${date(rows[0].date)} to ${date(rows.at(-1).date)}"><title>${esc(series.map(s=>s.name).join(', '))}</title>${grid}${dates}${markers}${paths}<line class="chart-cross" x1="0" x2="0" y1="${T}" y2="${H-B}"/></svg><div class="chart-tip" role="status"></div><label class="sr-only" for="${id}-range">Inspect ${esc(series[0].name)} by date</label><input class="chart-range" id="${id}-range" type="range" min="0" max="${rows.length-1}" value="${rows.length-1}" aria-label="Inspect ${esc(series[0].name)} by date">`;
 const svg=el.querySelector('svg'),tip=el.querySelector('.chart-tip'),cross=el.querySelector('.chart-cross'),range=el.querySelector('input');
 function inspect(index,show=true){index=Math.max(0,Math.min(rows.length-1,index));const p=rows[index];range.value=String(index);const text=`${date(p.date)}; ${series.map(s=>`${s.name}: ${tooltipFormat(p[s.key])}`).join('; ')}`;range.setAttribute('aria-valuetext',text);if(!show)return;tip.innerHTML=`<strong>${date(p.date)}</strong>${series.map(s=>`<div><span style="color:${s.color}">●</span> ${s.name}: ${tooltipFormat(p[s.key])}</div>`).join('')}`;tip.innerHTML+=visibleEvents.filter(e=>e.date===p.date).map(e=>`<div>${esc(e.title)}</div>`).join('');tip.style.display='block';tip.style.left=`${Math.max(4,Math.min(el.clientWidth-tip.offsetWidth-4,x(index)/W*el.clientWidth-tip.offsetWidth/2))}px`;cross.setAttribute('x1',x(index));cross.setAttribute('x2',x(index));cross.style.opacity='1';}
 inspect(rows.length-1,false);
 svg.addEventListener('pointermove',event=>{const box=svg.getBoundingClientRect(),px=(event.clientX-box.left)/box.width*W;const target=first+(px-L)/(W-L-R)*span;let closest=0;for(let i=1;i<rows.length;i++)if(Math.abs(Date.parse(rows[i].date)-target)<Math.abs(Date.parse(rows[closest].date)-target))closest=i;inspect(closest);});
 const hide=()=>{tip.style.display='none';cross.style.opacity='0';};svg.addEventListener('pointerleave',hide);range.addEventListener('input',()=>inspect(Number(range.value)));range.addEventListener('focus',()=>inspect(Number(range.value)));range.addEventListener('blur',hide);
}
function chartWindow(rows,days){const end=Date.parse(rows.at(-1)?.date);return days?rows.filter(p=>Date.parse(p.date)>=end-days*86400000):rows;}
function renderCharts() {
 renderResearchCharts();
 renderModelCharts();
 const b=data('bitcoin');if($('price-chart')&&b){const cutoff=state.period?Date.parse(b.asOf)-state.period*86400000:0;drawChart('price-chart',b.history.filter(p=>Date.parse(p.date)>=cutoff),[{key:'value',name:'Daily price',color:'#cd783e',width:2},{key:'ma50',name:'50D average',color:'#769277',width:1.4},{key:'ma200',name:'200D average',color:'#768dac',width:1.4}],{log:state.log,tooltipFormat:v=>money(v,2),events:state.eventMarkers?(data('calendar')?.pastEvents||[]):[],format:v=>valid(v)?money(v>=1000?v/1000:v,v>=1000?1:v<1?3:2)+(v>=1000?'k':''):'—'});}
 if($('sentiment-chart'))drawChart('sentiment-chart',data('sentiment').history,[{key:'value',name:'Fear & Greed',color:'#80956e'}],{format:v=>num(v,0),domain:[0,100],compactChart:true});
 if($('macro-chart')){const m=data('macro').metrics[state.macroMetric];drawChart('macro-chart',chartWindow(m.history,state.macroPeriod),[{key:'value',name:m.name,color:'#75916f',width:2}],{tooltipFormat:v=>m.unit==='billions'?money(v,3)+'B':m.unit==='percent'||m.unit==='yoy'?percent(v,3):num(v,4),format:v=>m.unit==='billions'?money(v/1000,2)+'T':m.unit==='percent'||m.unit==='yoy'?percent(v,1):num(v,1)});}
}
$('view').addEventListener('click',event=>{
 const period=event.target.closest('[data-period]');if(period){state.period=Number(period.dataset.period);render();}
 if(event.target.closest('#show-companies')){state.allCompanies=!state.allCompanies;$('companies').innerHTML=companyTable();MetricHelp.mount($('companies'));}
});
$('view').addEventListener('change',event=>{if(event.target.id==='log-scale'){state.log=event.target.checked;renderCharts();}if(event.target.id==='macro-select'){state.macroMetric=event.target.value;render();}});
$('view').addEventListener('input',event=>{if(event.target.id==='company-search'){state.search=event.target.value;state.allCompanies=false;$('companies').innerHTML=companyTable();MetricHelp.mount($('companies'));}});
function navigate(){const key=location.hash.slice(1);state.view=PAGES[key]?key:'overview';render();if(state.view==='narratives')loadNarratives();}
window.addEventListener('hashchange',navigate);
async function load(force=false) {
 if(state.busy)return;state.busy=true;$('refresh').disabled=true;$('refresh').innerHTML='<span aria-hidden="true">↻</span> Refreshing…';
 await Promise.allSettled(FEEDS.map(async key=>{
  try{const response=await fetch(`/api/${key}${force?'?refresh=1':''}`,{signal:AbortSignal.timeout(32000)});if(!response.ok)throw new Error('Request failed');const payload=await response.json();state.feeds[key]=key==='macro'?{data:payload,status:'current'}:payload;}
  catch{const prior=state.feeds[key];state.feeds[key]=prior?.data?{...prior,status:'stale',error:'Refresh failed. Showing previous data.'}:{data:null,status:'unavailable',error:'Source unavailable or request timed out.'};if(key==='macro'&&prior?.data)Object.values(prior.data.metrics).forEach(m=>m.status=m.value===null?'unavailable':'stale');}
  // Do not replace a focused search field while other feeds complete.
  const active=document.activeElement;if(active?.closest('#etf-import-form')||document.querySelector('#etf-import-form input[type=file]')?.files?.length||active?.id==='company-search'||active?.classList?.contains('chart-range')){renderStatus();}else render();
 }));
 await loadArchive();visitReady=true;saveVisit();state.lastRefreshed=new Date().toISOString();
 if(!document.activeElement?.closest('#etf-import-form')&&!document.querySelector('#etf-import-form input[type=file]')?.files?.length&&document.activeElement?.id!=='company-search')render();
 if(state.view==='narratives')loadNarratives(force);
 state.busy=false;renderStatus();$('refresh').disabled=false;$('refresh').innerHTML='<span aria-hidden="true">↻</span> Refresh data';
}
function priceComparison(){
 const b=data('bitcoin');if(!b)return '';
 const from=state.compareFrom||new Date(Date.parse(b.asOf)-30*86400000).toISOString().slice(0,10),to=state.compareTo||b.asOf;
 return `<details class="card compare-panel" id="price-comparison"><summary>Compare two dates</summary><div class="comparison-controls"><label>From<input id="compare-from" type="date" value="${esc(from)}" min="${b.history[0].date}" max="${b.asOf}"></label><label>To<input id="compare-to" type="date" value="${esc(to)}" min="${b.history[0].date}" max="${b.asOf}"></label><div id="comparison-result">${comparisonResult(from,to)}</div></div></details>`;
}
function comparisonResult(from,to){
 const b=data('bitcoin');if(!b||!from||!to||from>to||from<b.history[0].date||to>b.asOf)return '<p class="fine-print">Choose an ordered range within the available price history.</p>';
 const rows=b.history.filter(p=>p.date>=from&&p.date<=to);if(rows.length<2)return '<p class="fine-print">Choose a range with at least two daily observations.</p>';
 const a=rows[0],z=rows.at(-1);
 return `<strong class="${tone(z.value-a.value)}">${percent((z.value/a.value-1)*100,2,true)}</strong><p class="fine-print">${money(a.value,2)} → ${money(z.value,2)}<br>Actual observations: ${date(a.date)}–${date(z.date)}</p>`;
}
function renderResearchCharts(){
 const v=data('valuation');
 if(v){const rows=chartWindow(v.history,state.contextDays);drawChart('valuation-chart',rows,[{key:'price',name:'Daily price',color:'#cd783e'},{key:'realizedPrice',name:'Derived realized price',color:'#75916f'}],{format:v=>money(v/1000,1)+'k',tooltipFormat:v=>money(v,2)});drawChart('mvrv-chart',rows,[{key:'mvrv',name:'MVRV',color:'#75916f'}],{format:v=>num(v,2)+'×',tooltipFormat:v=>num(v,4)+'×',compactChart:true});}
 renderEtfCandles();
 const h=state.archive?.adoption;if(h?.snapshots?.length>1){const map=new Map();for(const p of h.snapshots)map.set(p.at.slice(0,10),{date:p.at.slice(0,10),value:p.total});drawChart('adoption-history-chart',[...map.values()],[{key:'value',name:'Reported corporate BTC',color:'#75916f'}],{format:v=>compact(v)+' BTC',tooltipFormat:v=>num(v,2)+' BTC',compactChart:true});}
}
async function loadArchive(){try{const r=await fetch('/api/history',{signal:AbortSignal.timeout(10000)});if(r.ok)state.archive=await r.json();}catch{state.archive={...state.archive,storageError:'Observation archive could not be loaded.'};}}
$('view').addEventListener('click',event=>{
 const context=event.target.closest('[data-context]');if(context){state.contextDays=Number(context.dataset.context);render();}
 const macro=event.target.closest('[data-macro-period]');if(macro){state.macroPeriod=Number(macro.dataset.macroPeriod);render();}
 if(event.target.closest('#mark-reviewed')&&visitReady){visitBaseline=visitSnapshot();saveVisit();render();$('checkin-feedback').textContent=visitStorageAvailable?'Check-in reviewed. New changes will appear here when available.':'Check-in reviewed for this visit. Browser storage is unavailable.';$('main').focus({preventScroll:true});}
});
$('view').addEventListener('change',event=>{
 if(event.target.id==='event-markers'){state.eventMarkers=event.target.checked;renderCharts();}
 if(event.target.id==='compare-from'||event.target.id==='compare-to'){state.compareFrom=$('compare-from').value;state.compareTo=$('compare-to').value;$('comparison-result').innerHTML=comparisonResult(state.compareFrom,state.compareTo);MetricHelp.mount($('view'));}
});
$('view').addEventListener('submit',async event=>{
 if(event.target.id!=='etf-import-form')return;event.preventDefault();
 const form=event.target,button=form.querySelector('button[type="submit"]'),message=$('import-message');button.disabled=true;
 try{
   const values=new FormData(form),file=values.get('file');if(!file?.size||file.size>500000)throw new Error('Choose a nonempty CSV smaller than 500 KB.');
   message.textContent='Validating reported sessions…';
   const response=await fetch('/api/etf/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csv:await file.text(),source:values.get('source'),url:values.get('url'),universe:values.get('universe')}),signal:AbortSignal.timeout(15000)});
   const payload=await response.json();if(!response.ok)throw new Error(payload.error||'Import failed.');
   state.feeds.etf=payload;await loadArchive();render();
   const note=$('import-message');if(note)note.textContent=`Imported ${payload.data.history.length} reported sessions. The original source and reporting coverage remain visible.`;
 }catch(error){message.textContent=error.message;message.classList.add('import-error');}finally{button.disabled=false;}
});

$('refresh').addEventListener('click',()=>load(true));
$('today').textContent=new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'});
navigate();load();
// Pick up background cache refreshes, and keep an open workspace useful without aggressive polling.
setTimeout(()=>load(),18000);
setInterval(()=>{if(!document.hidden)load();},60000);

let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(renderCharts,150);});
